#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <chrono>
long max_assignment(const vector<vector<int>>&a){int n=a.size();vector<long>u(n+1),v(n+1);vector<int>p(n+1),way(n+1);for(int i=1;i<=n;i++){p[0]=i;int j0=0;vector<long>minv(n+1,LONG_MAX/4);vector<char>used(n+1);do{used[j0]=true;int i0=p[j0],j1=0;long delta=LONG_MAX/4;for(int j=1;j<=n;j++)if(!used[j]){long cur=-a[i0-1][j-1]-u[i0]-v[j];if(cur<minv[j]){minv[j]=cur;way[j]=j0;}if(minv[j]<delta){delta=minv[j];j1=j;}}for(int j=0;j<=n;j++)if(used[j]){u[p[j]]+=delta;v[j]-=delta;}else minv[j]-=delta;j0=j1;}while(p[j0]);do{int j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0);}long total=0;for(int j=1;j<=n;j++){assert(a[p[j]-1][j-1]>-10000);total+=a[p[j]-1][j-1];}return total;}

int main(int argc,char**argv){assert(argc==4);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),fi(argv[2]);ofstream out(argv[3]);int n,m;in>>n>>m;assert(n==m);vector<Row>A(n);for(auto&r:A){int nn;in>>nn;for(int k=0;k<nn;k++){int j;Rat a;in>>j;readpoly(in,a.n);r.emplace(j,std::move(a));}}int nf;fi>>nf;for(int a=0;a<nf;a++){Rat f,q,cur;readpoly(fi,f.n);vector<vector<int>>cost(n,vector<int>(n,-100000));vector<int>hist(20);auto start=chrono::steady_clock::now();for(int i=0;i<n;i++)for(auto&[j,v]:A[i]){cur=v;int val=0;while(fmpq_mpoly_divides(q.n,cur.n,f.n,ctx)){fmpq_mpoly_swap(cur.n,q.n,ctx);val++;assert(val<20);}cost[i][j]=-val;hist[val]++;}long lower=-max_assignment(cost);out<<a<<' '<<lower<<'\n';for(int h:hist)out<<h<<' ';out<<'\n';cerr<<"FACTOR "<<a<<" TROPICAL_VALUATION_LOWER "<<lower<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
